import axios from "axios";

const API = axios.create({
  baseURL: "http://localhost:5000/api",
});

export const bookAppointment = (data) =>
  API.post("/appointments", data);

export const getQueue = () =>
  API.get("/queue");

export const getMedicalRecords = () =>
  API.get("/records");
